insert into public.quiz_questions (lesson_id, sort, prompt, options, correct_index, explanation) values
  ('hd-ess-01', 1, 'Tier 1 support is…', '["the deepest specialists", "the first human contact for common issues", "self-service only", "management"]'::jsonb, 1, 'Tier 1 handles first-contact common fixes.'),
  ('hd-ess-01', 2, 'Issues beyond your scope should be…', '["ignored", "escalated with notes", "closed", "deleted"]'::jsonb, 1, 'Escalate with context.'),
  ('hd-ess-01', 3, 'Employers value help-desk techs for…', '["silence", "communication + attitude", "typing speed only", "hardware only"]'::jsonb, 1, 'Soft skills matter as much as technical.'),
  ('hd-ess-02', 1, 'The first step on any contact is…', '["start fixing", "listen and confirm the issue", "escalate", "close it"]'::jsonb, 1, 'Understand before acting.'),
  ('hd-ess-02', 2, 'With a frustrated user you should…', '["match their anger", "acknowledge + focus on next steps", "hang up", "blame them"]'::jsonb, 1, 'Acknowledge and move to action.'),
  ('hd-ess-02', 3, 'Good communication means avoiding…', '["empathy", "jargon", "updates", "clarity"]'::jsonb, 1, 'Avoid jargon users don''t know.'),
  ('hd-ess-03', 1, 'Elevated access should be used…', '["freely", "only for the task at hand", "for curiosity", "to browse files"]'::jsonb, 1, 'Least privilege applies to techs too.'),
  ('hd-ess-03', 2, 'When you make a mistake you should…', '["hide it", "own and fix it", "blame a user", "ignore it"]'::jsonb, 1, 'Accountability builds trust.'),
  ('hd-ess-03', 3, 'User data must be…', '["shared", "respected/protected", "posted", "copied"]'::jsonb, 1, 'Protect privacy and follow policy.'),
  ('hd-ess-04', 1, 'Good ticket notes let…', '["only you continue", "the next tech continue", "no one continue", "managers only"]'::jsonb, 1, 'Anyone should be able to pick it up.'),
  ('hd-ess-04', 2, 'KB articles should be titled by…', '["internal code", "the symptom users search", "the tech''s name", "date"]'::jsonb, 1, 'Match how users describe it.'),
  ('hd-ess-04', 3, 'A KB article''s leverage is that it…', '["is hidden", "resolves issues repeatedly", "expires fast", "is private"]'::jsonb, 1, 'Reused many times via self-service.'),
  ('hd-ess-05', 1, 'Priority is derived from…', '["impact \u00d7 urgency", "ticket age", "alphabetical", "random"]'::jsonb, 0, 'Impact and urgency set priority.'),
  ('hd-ess-05', 2, 'A site-wide outage is typically…', '["P4", "P1", "closed", "low"]'::jsonb, 1, 'Broad, urgent = P1.'),
  ('hd-ess-05', 3, 'SLAs define…', '["response/resolution targets", "salaries", "hardware", "passwords"]'::jsonb, 0, 'Agreed time targets by priority.'),
