  ('hd-eve-01', 3, 'A reset password should be sent…', '["in plain email", "never in clear text", "via chat", "on a sticky note"]'::jsonb, 1, 'Never transmit in clear text.'),
  ('hd-eve-02', 1, 'A stuck print queue is cleared by…', '["reinstalling Windows", "restarting Print Spooler", "new toner", "a reboot only"]'::jsonb, 1, 'Restart the Print Spooler.'),
