  ('hd-eve-03', 1, 'Before VPN troubleshooting, confirm…', '["new laptop", "the user has internet", "AD reset", "Office reinstall"]'::jsonb, 1, 'No internet, no VPN.'),
  ('hd-eve-03', 2, 'Connected but names don''t resolve →', '["bad monitor", "DNS/routing", "low RAM", "dead NIC"]'::jsonb, 1, 'Likely DNS over the tunnel.'),
