  ('hd-eve-04', 1, 'Best first tool for delivery issues…', '["reboot Outlook", "message trace", "new mailbox", "reset password"]'::jsonb, 1, 'Message trace shows the path.'),
  ('hd-eve-04', 2, 'Missing mail may be caught by…', '["rules/junk/quarantine", "the CPU", "DNS only", "the printer"]'::jsonb, 0, 'Check rules, junk, quarantine.'),
  ('hd-eve-04', 3, 'A corrupt Outlook profile is fixed by…', '["new PC", "rebuilding the profile", "new license", "BIOS reset"]'::jsonb, 1, 'Rebuild the mail profile.'),
  ('hd-eve-05', 1, 'Incognito working but normal failing suggests…', '["server down", "cache/extension", "dead NIC", "bad RAM"]'::jsonb, 1, 'Stale cache or an extension.'),
