  ('hd-t1-01', 2, 'First checks for a slow PC…', '["buy new PC", "startup apps/disk/malware", "repaint", "new monitor"]'::jsonb, 1, 'Startup load, disk/RAM, malware.'),
  ('hd-t1-01', 3, 'Clues to app errors live in…', '["Event Viewer", "Paint", "the BIOS", "the router"]'::jsonb, 0, 'Event Viewer logs errors.'),
  ('hd-t1-02', 1, 'A yellow ! in Device Manager means…', '["healthy", "a driver/hardware problem", "low disk", "a virus"]'::jsonb, 1, 'It flags a device problem.'),
